#include <stdio.h>

int main() {
    int num = 10;
    int *ptr = &num;
    printf("Value of num: %d\n", num);
    printf("Address of num: %p\n", (void*)&num);
    printf("Value in ptr (address it holds): %p\n", (void*)ptr);
    return 0;
}

#include <stdio.h>

int main() {
    int value = 25;
    int *p = &value;
    printf("The value accessed through the pointer is: %d\n", *p);
    return 0;
}

#include <stdio.h>

int main() {
    int data = 50;
    int *dataPtr = &data;
    printf("Original value of data: %d\n", data);
    *dataPtr = 100;
    printf("Value of data after modification via pointer: %d\n", data);
    return 0;
}

#include <stdio.h>

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *ptr = arr;
    printf("Value of the third element using pointer arithmetic: %d\n", *(ptr + 2));
    printf("Value of the fifth element using pointer arithmetic: %d\n", *(ptr + 4));
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int num1, num2;
    scanf("%d%d", &num1, &num2);
    printf("Before swap: num1 = %d, num2 = %d\n", num1, num2);
    swap(&num1, &num2);
    printf("After swap: num1 = %d, num2 = %d\n", num1, num2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);
    int *arr = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) scanf("%d", &arr[i]);
    printf("Dynamically allocated array elements: ");
    for (int i = 0; i < N; i++) printf("%d%s", arr[i], i == N-1 ? "\n" : " ");
    free(arr);
    printf("Memory freed successfully.\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

void reverseString(char *str) {
    int len = strlen(str);
    for (int i = 0, j = len-1; i < j; i++, j--) {
        char t = str[i];
        str[i] = str[j];
        str[j] = t;
    }
}

int main() {
    char str[51];
    scanf("%s", str);
    printf("Original string: %s\n", str);
    reverseString(str);
    printf("Reversed string: %s\n", str);
    return 0;
}

#include <stdio.h>

int sumArray(int *arr, int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) sum += arr[i];
    return sum;
}

int main() {
    int myArray[] = {1, 2, 3, 4, 5};
    int sum = sumArray(myArray, 5);
    printf("The sum of array elements is: %d\n", sum);
    return 0;
}

#include <stdio.h>

int main() {
    int x = 10;
    int *p = &x;
    int **pp = &p;
    printf("Value of x (accessed via double pointer): %d\n", **pp);
    **pp = 20;
    printf("New value of x (after modification via double pointer): %d\n", x);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int N;
    scanf("%d", &N);
    char **studentNames = (char **)malloc(N * sizeof(char *));
    for (int i = 0; i < N; i++) {
        studentNames[i] = (char *)malloc(21 * sizeof(char));
        scanf("%s", studentNames[i]);
    }
    printf("Student Names:\n");
    for (int i = 0; i < N; i++) printf("%d. %s\n", i+1, studentNames[i]);
    for (int i = 0; i < N; i++) free(studentNames[i]);
    free(studentNames);
    printf("All memory freed successfully.\n");
    return 0;
}
